import type { Picture } from '@sveltejs/enhanced-img';

interface ArticleBase {
	/** HTML generated by mdsvex */
	type: string;
	content?: string;
	title: string;
	description: string;
	created?: Date;
	updated?: Date;
	slug: string;
}

export interface BlogPost extends ArticleBase {
	type: 'post';
	content: string;
	created: Date;
	updated: Date;
}

export interface BlogProject extends ArticleBase {
	type: 'project';
	/** Git repository to the project */
	repository?: string;
	/** Link to the project, also used to generate the preview */
	link: string;
	/** A generated preview of the project */
	preview: Picture | string;
}
